-- quest_template: insert only eligible quests
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`ID` int unsigned NOT NULL, `QuestType` tinyint unsigned NOT NULL, `QuestSortID` smallint NOT NULL, `RewardXPDifficulty` int unsigned NOT NULL, `RewardXPMultiplier` float NOT NULL, `RewardFactionID1` int unsigned NOT NULL, `RewardFactionValue1` int NOT NULL, `Flags` int unsigned NOT NULL, `AllowableRaces` bigint unsigned NOT NULL, `LogTitle` mediumtext NOT NULL, `LogDescription` mediumtext NOT NULL, `QuestDescription` mediumtext NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`ID`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`ID`, `QuestType`, `QuestSortID`, `RewardXPDifficulty`, `RewardXPMultiplier`, `RewardFactionID1`, `RewardFactionValue1`, `Flags`, `AllowableRaces`, `LogTitle`, `LogDescription`, `QuestDescription`, `VerifiedBuild`, `note`) VALUES
(93786, 2, 16591, 5, 1.0, 0, 0, 36700168, 12261800583900083122, 'A Message in Blood', 'Slay $1oa Meadowsbrook Farmhands, then return to Krom''rosh with news of your success.', 'Does your blade thirst for human blood, $n?\r\n\r\nSome years ago, the human defectors laid claim to a small farm to the southwest across the river. With the area rich in lumber and stone, it was only a matter of time before they expanded their reach to the keep along the eastern shore known as Farholde.\r\n\r\nOur first skirmishes would have ended in our favor if we''d had the numbers. It''s time to remind them of our presence.\r\n\r\nDisrupt their farming efforts. Take no prisoners. Send them a clear message.', 0, 'EG Link @70862; Wowhead quest 93786, NPC 256418 relation corroboration'),
(95603, 2, 16591, 4, 1.0, 2826, 5, 36700168, 6130900294268439629, 'Bats in the Belfry', 'Kill 5 Roosting Duskbats in the Farholde Cathedral for Sister Rowland.', 'Since brother Lowley and I began serving Farholde in a more secular capacity, the church here has fallen into disuse. I''d like to think that once the fighting is over, we will be able to bring the Light back to this place. Although, I fear that may not be for a long while...\r\n\r\nStill, we need to keep the church in working order, in the hope that day will come.\r\n\r\nTo that end, a colony of bats has taken to roosting in the upper stories of the church. It would be a great help if you could remove them.', 0, 'EG Link @70862; Wowhead quest 95603, NPC 262031 relation corroboration');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `quest_template` t WHERE t.`ID` = s.`ID`) AND EXISTS (SELECT 1 FROM `everlake_slice6_ready` g WHERE g.`quest` = s.`ID`);
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestSortID`, `RewardXPDifficulty`, `RewardXPMultiplier`, `RewardFactionID1`, `RewardFactionValue1`, `Flags`, `AllowableRaces`, `LogTitle`, `LogDescription`, `QuestDescription`, `VerifiedBuild`) SELECT `ID`, `QuestType`, `QuestSortID`, `RewardXPDifficulty`, `RewardXPMultiplier`, `RewardFactionID1`, `RewardFactionValue1`, `Flags`, `AllowableRaces`, `LogTitle`, `LogDescription`, `QuestDescription`, `VerifiedBuild` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_template', s.`ID`, '2026_11_10_00_world_everlake_import_slice6.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_00_world_everlake_import_slice6.sql', `note` = s.`note`;
